/**
 * Pure rendering for the v2 catalog.
 *
 * `renderCatalog` is the canonical renderer: it produces a single flat
 * TypeScript file per catalog root (app, element, or org). Per-kind emission
 * dialect lives on CatalogFacet.renderEntry (and deferred graph meta) — this
 * file only orchestrates imports, bag order, and indentation.
 */
import { catalogKindsForRoot, catalogBagForRefKind, } from "../graph/index.js";
import { sdkPackageSpecifier } from "../internal/sdk-package.js";
import { safeCatalogKey } from "./render-helpers.js";
function bagName(kind) {
    const bag = catalogBagForRefKind(kind);
    if (bag === undefined) {
        throw new Error(`catalog bag name unknown for ref kind "${kind}" — register a CatalogFacet or deferred meta`);
    }
    return bag;
}
/**
 * Render a single flat catalog file. App/element catalogs use `appCatalog()` /
 * `elementCatalog()` so `__kind` stays inside the factory. The org catalog uses
 * `orgCatalog()`. Behavioral kinds (automation/agent) have their own entity
 * files — their refs land here too, but the caller sources them by calling
 * `.ref()` on each entity file's `defineX(...)` result
 * (`src/catalog/from-authoring.ts`), not from server-side import data.
 *
 * @deprecated `automationTriggerKinds` is no longer used — pass nothing or omit.
 */
export function renderCatalog(root, refs, _automationTriggerKinds, ownFile) {
    const isApp = root.kind === "app" || root.kind === "element";
    // Graph CatalogFacet (+ deferred meta) drives which kinds belong on this root
    // and their emission order — no hard-wired KIND_ORDER / bag lists here.
    const usedMeta = catalogKindsForRoot(root.kind).filter((m) => refs.some((r) => r.__kind === m.refKind));
    // Fields resolve live off `ownFile` (identity + fields come straight from
    // the app/element's own `.ref()` call) — never rendered as baked entries,
    // so `fieldRef` never needs importing and the per-entry loop skips "field".
    const liveMeta = ownFile !== undefined ? usedMeta.filter((m) => m.refKind !== "field") : usedMeta;
    const factoryNames = new Set();
    if (isApp) {
        factoryNames.add(root.kind === "element" ? "elementCatalog" : "appCatalog");
    }
    else {
        factoryNames.add("orgCatalog");
    }
    for (const m of liveMeta)
        factoryNames.add(m.factoryName);
    const entryIndent = isApp ? "      " : "    ";
    for (const m of liveMeta) {
        const kindRefs = refs.filter((r) => r.__kind === m.refKind);
        let everyEntryUsesVariantFactory = kindRefs.length > 0;
        for (const ref of kindRefs) {
            const rendered = m.renderEntry({
                ref,
                keyName: ref.refName,
                baseIndent: entryIndent,
            });
            if (rendered.omitsDefaultFactory !== true) {
                everyEntryUsesVariantFactory = false;
            }
            for (const f of rendered.extraFactories ?? [])
                factoryNames.add(f);
        }
        if (everyEntryUsesVariantFactory)
            factoryNames.delete(m.factoryName);
    }
    const lines = [];
    if (ownFile !== undefined) {
        lines.push(`import ${ownFile.identifier} from ${JSON.stringify(ownFile.importPath)};`);
    }
    lines.push(`import { ${[...factoryNames].sort().join(", ")} } from "${sdkPackageSpecifier("catalog")}";`);
    lines.push("");
    if (isApp) {
        const catalogFn = root.kind === "element" ? "elementCatalog" : "appCatalog";
        if (ownFile !== undefined) {
            lines.push(`const __own = ${ownFile.identifier}.ref(${JSON.stringify(root.refName)});`);
            lines.push("");
        }
        lines.push(`export const ${root.refName} = ${catalogFn}(`);
        lines.push(ownFile !== undefined
            ? `  { refName: __own.refName, name: __own.name, ...(__own.namespace !== undefined ? { namespace: __own.namespace } : {}) },`
            : `  { refName: ${JSON.stringify(root.refName)}, name: ${JSON.stringify(root.name)}${root.namespace !== undefined ? `, namespace: ${JSON.stringify(root.namespace)}` : ""} },`);
        lines.push(`  {`);
        for (const m of usedMeta) {
            const bag = bagName(m.refKind);
            if (m.refKind === "field" && ownFile !== undefined) {
                lines.push(`    ${bag}: __own.fields,`);
                continue;
            }
            const kindRefs = refs
                .filter((r) => r.__kind === m.refKind)
                .sort((a, b) => a.refName.localeCompare(b.refName));
            lines.push(`    ${bag}: {`);
            for (const ref of kindRefs) {
                const rendered = m.renderEntry({
                    ref,
                    keyName: ref.refName,
                    baseIndent: entryIndent,
                });
                lines.push(...rendered.lines);
            }
            lines.push(`    },`);
        }
        lines.push(`  },`);
        lines.push(`);`);
    }
    else {
        lines.push(`export const org = orgCatalog({`);
        for (const m of usedMeta) {
            const bag = bagName(m.refKind);
            const kindRefs = refs
                .filter((r) => r.__kind === m.refKind)
                .sort((a, b) => a.refName.localeCompare(b.refName));
            lines.push(`  ${bag}: {`);
            for (const ref of kindRefs) {
                const rendered = m.renderEntry({
                    ref,
                    keyName: ref.refName,
                    baseIndent: entryIndent,
                });
                lines.push(...rendered.lines);
            }
            lines.push(`  },`);
        }
        lines.push(`});`);
        lines.push("");
        lines.push(`export type Ref = typeof org;`);
    }
    lines.push("");
    return lines.join("\n");
}
/** @deprecated Use renderCatalog instead. */
export function renderFragment(ref) {
    const lines = [
        `export const ${ref.refName} = {`,
        `  __kind: ${JSON.stringify(ref.__kind)},`,
        `  refName: ${JSON.stringify(ref.refName)},`,
        `  name: ${JSON.stringify(ref.name)},`,
    ];
    if (ref.parent !== undefined)
        lines.push(`  parent: ${JSON.stringify(ref.parent)},`);
    if (ref.__kind === "field") {
        const field = ref;
        lines.push(`  fieldType: ${JSON.stringify(field.fieldType)},`);
        if (field.tags !== undefined) {
            lines.push(`  tags: ${JSON.stringify(field.tags)},`);
        }
    }
    if (ref.__kind === "automation") {
        lines.push(...renderMemberBag("trigger", ref.trigger));
        lines.push(...renderMemberBag("outputs", ref.outputs));
    }
    lines.push(`} as const;`, "");
    return lines.join("\n");
}
/**
 * Render a nested ref bag (`trigger` / `outputs`) inside an automation fragment:
 * `bag: { <key>: { __kind, refName, name, parent }, … }`. Keys are sorted for
 * byte-stability; an empty/absent bag emits nothing.
 */
function renderMemberBag(bag, members) {
    const keys = Object.keys(members ?? {}).sort();
    if (keys.length === 0)
        return [];
    const entries = keys.map((key) => {
        const m = members[key];
        const parts = [
            `__kind: ${JSON.stringify(m.__kind)}`,
            `refName: ${JSON.stringify(m.refName)}`,
            `name: ${JSON.stringify(m.name)}`,
            ...(m.parent !== undefined ? [`parent: ${JSON.stringify(m.parent)}`] : []),
        ];
        return `    ${safeCatalogKey(key)}: { ${parts.join(", ")} },`;
    });
    return [`  ${bag}: {`, ...entries, `  },`];
}
/** @deprecated Use renderCatalog instead. */
export function renderBarrel(root, entries) {
    const imports = [...entries]
        .sort((a, b) => (a.importPath < b.importPath ? -1 : a.importPath > b.importPath ? 1 : 0))
        .map((e) => `import { ${e.refName} } from ${JSON.stringify(e.importPath)};`);
    const lines = [];
    if (imports.length > 0)
        lines.push(...imports, "");
    lines.push(`export const ${root.refName} = {`);
    lines.push(`  __kind: ${JSON.stringify(root.kind)},`);
    lines.push(`  refName: ${JSON.stringify(root.refName)},`);
    lines.push(`  name: ${JSON.stringify(root.name)},`);
    for (const meta of catalogKindsForRoot(root.kind)) {
        const refNames = entries
            .filter((e) => e.kind === meta.refKind)
            .map((e) => e.refName)
            .sort();
        if (refNames.length === 0)
            continue;
        lines.push(`  ${meta.catalogBag}: { ${refNames.join(", ")} },`);
    }
    lines.push(`} as const;`, "");
    return lines.join("\n");
}
